// ARC-39.02 / §13 / §XXIX — the two-commit closeout validator (advisory §10). This is a SEPARATE proof from
// the completion loop: the loop proves product BEHAVIOR; this validates the PROVENANCE of the proof artifact.
// HASH_PROOF.json is generated by the completion-loop test at Commit B; this gate checks the clauses are all
// true and DERIVED, the §27 question PASSed, and the Git relationship holds — implementation_commit is a real
// ancestor of HEAD (Commit A) and is NOT HEAD itself (Commit B/later). Not wired into test:ci until HASH_PROOF
// exists (post-closeout); never in prebuild (it uses git).
// Run: node tests/architect-closeout.test.mjs
import { readFileSync } from "node:fs";
import { execSync } from "node:child_process";

let pass = 0, fail = 0;
const ok = (c, m) => { if (c) { pass++; } else { fail++; console.log("FAIL", m); } };

const path = new URL("../../docs/architecture-2525/HASH_PROOF.json", import.meta.url);
let hp;
try { hp = JSON.parse(readFileSync(path, "utf8")); } catch { console.log("FAIL HASH_PROOF.json missing — run the closeout (WRITE_HASH_PROOF=1 IMPLEMENTATION_COMMIT=<A>)"); process.exit(1); }

// ── the proof is generated by the test and its §27 verdict is the AND of DERIVED clauses ──
ok(hp.generated_by_test === true, "HASH_PROOF is generated_by_test (never hand-typed)");
ok(hp.clauses && hp.clauses.altered && hp.clauses.remembers && hp.clauses.verify_reverse && hp.clauses.survives, "all four §27 clauses are true (altered · remembers · verify-reverse · survives)");
ok(hp.final_question_pass === true, "§27 final_question_pass is true");
ok(hp.final_question_pass === (hp.clauses.altered && hp.clauses.remembers && hp.clauses.verify_reverse && hp.clauses.survives), "final_question_pass is the AND of the clauses, not a literal");

// ── the recorded shape matches the proven loop ──
ok(/^[0-9a-f]{64}$/.test(hp.project_hash) && /^[0-9a-f]{64}$/.test(hp.package_hash), "project_hash and package_hash are 64-hex SHA-256");
ok(hp.current_revision_id === "R2" && hp.entity_count === 13 && hp.event_count === 2 && hp.snapshot_count === 1, "the recorded R2 shape matches the completion loop (13 entities, 2 events, 1 snapshot)");
ok(typeof hp.canonical_serialization_byte_count === "number" && hp.canonical_serialization_byte_count > 0, "canonical_serialization_byte_count recorded");

// ── §13/§XXIX — the two-commit Git relationship: implementation_commit == A, an ancestor of HEAD, != HEAD (B) ──
let git = true, head = "", implInHistory = false, implIsHead = false;
try {
  head = execSync("git rev-parse HEAD", { encoding: "utf8" }).trim();
  const impl = hp.implementation_commit;
  ok(/^[0-9a-f]{40}$/.test(impl), `implementation_commit is a real 40-hex SHA (got ${impl})`);
  try { execSync(`git merge-base --is-ancestor ${impl} HEAD`, { stdio: "ignore" }); implInHistory = true; } catch { implInHistory = false; }
  implIsHead = impl === head;
  ok(implInHistory, "implementation_commit (A) is an ancestor of HEAD");
  ok(!implIsHead, "implementation_commit (A) is NOT HEAD — the proof (B) is a later commit");
} catch { git = false; console.log("NOTE: git unavailable — skipped the ancestry checks (content checks still enforced)"); }

console.log(`\narchitect-closeout: ${pass} passed, ${fail} failed${git ? "" : " (git checks skipped)"}`);
if (fail) process.exit(1);
